      about_lead: "我们买货、贴牌、发货，做的是售后市场的汽车电器件。我们不是工厂，这页也不假装是——它讲清楚我们实际做什么，好让你判断我们是不是适合你市场的供应商。",
      about_s1_h: "我们做什么",
