      about_s1_p2: "我们卖的每个型号都在站上列着 OE 号、交叉号和适配。这份清单就是产品本身：说不出它替代哪个 OE 号，我们就不上架。",
      about_s2_h: "货是怎么做出来的",
      about_s2_p1: "我们是工贸一体的贸易公司，有自有品牌，这一点明说。WEILI 的货由长期合作的工厂为我们生产——和你现在买的多数售后品牌是一个做法。",
      about_s2_p2: "我们控制的是件周边的一切：OE 与交叉号清单、规格、来料检验、包装与质保。哪批货出自哪条线，我们清楚；你问某个料号是哪家工厂做的，我们会告诉你。",
      about_s3_h: "我们在哪",
      about_s3_p1: "办公室在广州白云区——全中国的汽配商都去那里进货。现货几天内发出，出口走广州港；具体港口和条款在报价里确认。",
