      about_s6_p: "每个买家第一句话都是「这个号你有没有」——通常还配一张坏件标签的照片。与其一个一个答，我们干脆把 {n} 个型号连同 OE 号和交叉号全部放上网，用九种语言，让拉各斯的师傅或迪拜的柜台凌晨两点也能自己查。",
      policy_upd: "更新日期",
      priv_h1: "隐私政策",
      priv_lead: "这页只讲具体的事：我们收到什么、为什么留着、怎么删掉。",
      priv_s1_h: "本政策的适用范围",
      priv_s1_p: "本政策说明：你使用本站型号查询功能、或就某个件联系我们时，我们处理哪些数据。它不适用于我们链接到的其他公司网站。",
      priv_s2_h: "你主动提供给我们的信息",
      priv_s2_p: "我们只收到你发给我们的内容：姓名、公司、国家，你询价的型号与数量，车型信息，订单信息，以及你附上的照片或文件。你可以通过 WhatsApp、邮件或你选择的任何其他渠道发送这些内容。",
      priv_s3_h: "自动收集的信息",
      priv_s3_p: "我们的托管服务商保存标准服务器日志（IP 地址、浏览器、请求页面、时间），用于运行网站和阻止滥用。本站还会把语言选择记在你自己的浏览器里（localStorage 键名 <code>ymy_lang</code>）；该值只留在你的设备上，不会发给我们。",
      priv_s4_h: "Cookie 与统计",
      priv_s4_p1: "本站不设置任何 Cookie——不用于广告，也不用于统计。语言偏好以 localStorage（而非 Cookie）保存在你的浏览器中，清除浏览器数据即可删除。",
      priv_s4_p2: "页面浏览量用无 Cookie 的计数器（GoatCounter）做汇总统计：它会收到页面路径、来源页面和你的浏览器语言。它不设置 Cookie，也不保留任何能让我们识别你的标识，所以我们看到的是「这个页面从该国被打开 N 次」，而不是谁打开的。在型号查询框里输入的搜索词可能被记录，且只记录型号本身。如果你的浏览器发送 Do Not Track 信号，计数会关闭。",
      priv_s5_h: "我们如何使用你的信息",
      priv_s5_p: "用于回复你的询盘、制作报价、安排生产与发货、保存会计与出口单证所需的记录，以及排查并修复网站故障。我们不会用你的询盘去建立广告画像。",
      priv_s6_h: "我们与谁共享",
      priv_s6_p: "我们只在为你提供服务所必需的范围内共享数据：托管服务商（GitHub Pages）处理访问日志；你主动在那里发给我们的消息由 WhatsApp（Meta）处理；货代、快递公司与海关当局会收到交付所需的运输信息。我们不出售、不出租你的数据，也不会把你的客户名单提供给其他买家。",
      priv_s7_h: "我们保存多久",
      priv_s7_p: "询盘与订单记录会在为你提供服务以及满足法律、税务和出口要求所需的期间内保存。你要求我们停止发送营销信息后，我们立即停止。",
      priv_s8_h: "你的选择",
      priv_s8_p: "你可以要求我们提供你发来的信息的副本、要求更正或要求删除。写信到下方邮箱，我们会按请求处理。删除询盘记录可能导致我们无法再为该订单报价或提供支持。",
      priv_s9_h: "安全",
      priv_s9_p: "询盘数据存放在有访问控制的系统中，仅限处理你订单的员工访问。没有任何系统是绝对安全的，通过 WhatsApp 或普通电子邮件发送的消息并非由我们做端到端加密。",
      priv_s10_h: "未成年人",
      priv_s10_p: "本站是企业对企业（B2B）的零件目录，不面向未成年人，我们也不会在知情的情况下收集其数据。",
      priv_s11_h: "本政策的变更",
      priv_s11_p: "如果我们改变数据处理方式，会更新本页及上方日期。在此发布的版本为适用版本。",
      ret_h1: "退款与退货",
      ret_lead: "寄回任何东西之前，请先联系我们。以下是质保范围、不在范围内的情形，以及索赔的处理方式。",
      ret_s1_h: "概述",
      ret_s1_p: "我们希望这个件装得上、用得住。如果出了问题，请先联系我们再寄回，以便我们确认情况并给你一个退货授权号（RMA）。未取得 RMA 号就寄回的件，可能被拒收或在海关被延误。",
      ret_s2_h: "质保覆盖什么",
      ret_s2_p: "我们的件按品类提供 12 至 24 个月质保。你这单的确切期限写在报价单和发票上，双方以同一个数字为准。质保覆盖在该件所标注的车辆上正常使用情况下出现的制造缺陷。",
      ret_s3_h: "不在质保范围内的情形",
      ret_s3_p: "质保不包括：事故、碰撞或火灾造成的损坏；安装错误，或因线束、接头、电压问题导致的安装损坏；误用、疏于保养、进水，或未经授权的维修与改装；正常磨损；因未核对 OE 号或交叉号而为错误车型订购的件；以及未凭承运方记录向我们报告的运输损坏。",
      ret_s4_h: "如何提出索赔",
      ret_s4_p: "1) 把发票或订单号以及型号发给我们。2) 发该件的照片或短视频，如有可能，附上整车与故障码。3) 告诉我们车型、年款和发动机，以及这个件具体哪里不对。4) 我们审核该案——每个案子按其自身证据判断，我们可能要求寄回检测。5) 索赔通过后，我们出具 RMA 号，并与你确认是换货、开冲抵单还是退款。",
      ret_s5_h: "运费与时限",
      ret_s5_p: "除属我方责任外（发错件、件与描述不符，或经我们确认的缺陷），退回运费由买家承担。谁承担运费，我们在退货发出前书面确认。检测及换货或冲抵按每案处理；我们会在 RMA 号中书面告知预计时间，而不在本页承诺固定天数。",
      ret_s6_h: "换货与退款",
      ret_s6_p: "索赔通过后，我们换货、在你下一单开冲抵单，或退还发票金额——以我们书面确认的那种为准。在可行的情况下，退款按原支付渠道退回。",
      ret_s7_h: "联系方式",
      ret_s7_p: "把索赔与问题发到下文的 WhatsApp 号码或邮箱。请附上订单号，以便我们尽快找到你的档案。",
