      cd_p0301_name: "第 1 缸失火",
      cd_p0301_lead: "P0301 是最好用的失火码：它直接点名了缸号。送到我们手上的案例大多是点火系统，而其中多数是线圈，不是火花塞。",
      cd_p0301_b_0: "这个码到底是什么",
      cd_p0301_b_1: "ECU 会监测第 1 缸点火后曲轴加速多少，并与其他缸比较。当第 1 缸的贡献变小，就记下 P0301。它是在连续第二个行驶循环仍出现故障时才置位——这也解释了为什么消失一周又回来的 P0301，通常是件受热后开始失效，而不是线断了。",
      cd_p0301_b_2: "第 1 缸不一定在发动机最前面。大多数横置四缸机里它在正时皮带那一端，但也有厂家从变速箱那端开始编号。下单前先确认编号方式，法系和韩系发动机尤其要注意。",
      cd_p0301_b_3: "你会感觉到什么",
      cd_p0301_b_4_l_0: "怠速抖动，2,000 转以上基本消失——线圈受热失效的典型特征",
      cd_p0301_b_4_l_1: "发动机灯常亮，急加速时闪烁",
      cd_p0301_b_4_l_2: "冷启动后 10–20 分钟开始抖动，潮湿天气更明显",
      cd_p0301_b_4_l_3: "排气管有汽油味，油耗明显上升",
      cd_p0301_b_4_l_4: "P0301 与 P0171 同时出现——这种组合通常是某一缸偏稀，而不是点火弱",
      cd_p0301_b_5: "我们的排查顺序",
      cd_p0301_b_6_h_0: "原因",
      cd_p0301_b_6_h_1: "对应品类",
      cd_p0301_b_6_h_2: "为什么排在前面",
      cd_p0301_b_6_c_0_0: "火花塞磨损、积碳或热值不对",
      cd_p0301_b_6_c_0_2: "最便宜的件、最快的检查。绝缘体开裂造成的失火，跟线圈坏了一模一样。",
      cd_p0301_b_6_c_1_0: "第 1 缸的点火线圈",
      cd_p0301_b_6_c_1_2: "在 10 万公里以上、每缸独立线圈的发动机上，这是最常见的原因。",
      cd_p0301_b_6_c_2_0: "分缸线或护套（仅限废火式点火发动机）",
      cd_p0301_b_6_c_2_2: "线磨损通常影响两缸，护套裂开只影响一缸。",
      cd_p0301_b_6_c_3_0: "喷油嘴渗漏或堵塞",
      cd_p0301_b_6_c_3_2: "偏稀的缸会失火。如果那一侧的燃油修正值偏高，就要怀疑喷油嘴。",
      cd_p0301_b_6_c_4_0: "该气道的进气垫漏气",
      cd_p0301_b_6_c_4_2: "只让一个缸偏稀，冷车时更明显。",
      cd_p0301_b_7: "买之前先测",
      cd_p0301_b_8_l_0: "把线圈和第 2 缸对调，清码。如果失火变成 P0302，就是线圈坏了。这一招能定性大部分案例，而且不花钱。",
      cd_p0301_b_8_l_1: "如果码还留在第 1 缸，把火花塞拆出来看：黑且湿 = 供油过多或点火弱；发白、电极起泡 = 偏稀或点火过早。",
      cd_p0301_b_8_l_2: "把线圈一次侧电阻跟一个确定好的缸上的线圈比——不要跟手册值比，不同线圈系列的数不一样。",
      cd_p0301_b_8_l_3: "看看护套内侧有没有一条细灰的爬电碳痕，火花塞井里有没有机油。这两种造成的失火，换新线圈也治不好，除非先把漏油处理掉。",
      cd_p0301_b_9: "最贵的那个错误",
      cd_p0301_b_10: "在一辆 6 万公里的车上，「既然盖子都拆了」就把四个线圈全换掉。通常病因是火花塞，线圈是受害者：磨损的火花塞需要更高的击穿电压，压力全落在圈上。换线圈时把火花塞一起换，否则一年内这单还得返。",
      cd_p0301_qa_q0: "P0301 是线圈坏还是火花塞坏？",
      cd_p0301_qa_a0: "通常两个都有份：火花塞磨损，线圈负担加重最后坏掉。把线圈换到别的缸就能知道此刻是哪个死了；火花塞无论如何都该换。",
      cd_p0301_qa_q1: "有 P0301 还能开吗？",
      cd_p0301_qa_a1: "轻点开，别跑远。灯常亮＝这周去修；灯在闪＝马上停，因为燃油正在三元催化里燃烧。",
      cd_p0301_pn_0: "第 1 缸线圈——最常见的换法",
