      cd_p0301_b_2: "الأسطوانة 1 ليست دائمًا في مقدمة المحرك. في معظم المحركات الأربعية العرضية تكون عند طرف سير التوقيت، لكن بعض المصنّعين يرقّمون من جهة ناقل الحركة. تأكد من الترقيم قبل الطلب، خصوصًا في المحركات الفرنسية والكورية.",
      cd_p0301_b_3: "ما ستلاحظه",
