      cd_p0301_b_4_l_3: "رائحة وقود من العادم وارتفاع ملحوظ في الاستهلاك",
      cd_p0301_b_4_l_4: "ظهور P0301 مع P0171 — هذا التوليف يعني عادةً أسطوانة فقيرة لا شرارة ضعيفة",
