      cd_p0301_b_8_l_1: "إذا بقي الرمز على الأسطوانة 1 فانزع الشمعة واقرأها: سوداء ورطبة تعني وقودًا زائدًا أو شرارة ضعيفة، وبيضاء بقطب متقشر تعني خليطًا فقيرًا أو تقديمًا زائدًا للتوقيت.",
      cd_p0301_b_8_l_2: "قارن مقاومة الملف الابتدائية بملف على أسطوانة تعرف أنها سليمة — لا بقيمة من الكتاب، لأن القيمة تختلف بين عائلات الملفات.",
      cd_p0301_b_8_l_3: "ابحث عن مسار كربوني رمادي رفيع داخل الغطاء، وعن زيت في جيب الشمعة. كلاهما يُحدث عدم إشعال لا يصلحه ملف جديد قبل معالجة تسريب الزيت.",
