      faq_h: "Questions fréquentes",
      faq_lead: "Six questions posées avant la première commande. Autre chose ? Écrivez sur WhatsApp, réponse sous un jour ouvré.",
      faq_q1: "Quel est le MOQ (quantité minimale) ?",
      faq_a1: "Le MOQ dépend de la pièce et de l'emballage. Envoyez les modèles et les quantités, nous confirmons ligne par ligne.",
