      about_h2: "Un fournisseur de pièces à Guangzhou avec ses propres marques",
      about_p1: "Nous sommes Guangzhou Yumengyang Auto Parts Co., Ltd, fondée en 2002 dans le district de Baiyun, à Guangzhou : 4 filiales et deux marques propres, WEILI (allumage, capteurs, circuit carburant) et STANDOUT.",
      about_p2: "Les pièces sont stockées et expédiées depuis un entrepôt de plus de 10 000 m² à Guangzhou. Les pièces WEILI sont fabriquées par des partenaires certifiés ISO 9001 et IATF 16949 ; nous maîtrisons la liste OE, le contrôle à réception, l'emballage et la garantie.",
      about_p3: "Nous fournissons des distributeurs et des ateliers dans plus de 25 pays — dont le Pérou, la Bolivie, l'Afrique du Sud, l'Irak, l'Iran, la Syrie et l'Égypte.",
