      ws1_k: "Ce que nous fournissons",
      ws1_h: "23 gammes, 6 819 références",
      ws1_p: "Bobines d'allumage, pompes à carburant, sondes lambda, capteurs ABS, boîtiers papillon et bougies — chaque pièce est référencée par son numéro OE, devis sous un jour ouvré.",
      ws1_go: "Voir le catalogue →",
