      ws2_h: "WEILI et STANDOUT",
      ws2_p: "Fabriquées par des partenaires certifiés ISO 9001 / IATF 16949. Nous contrôlons la liste OE, le contrôle à réception, l'emballage et la garantie — c'est pourquoi les références correspondent.",
      ws2_go: "Voir les catégories →",
