      ws3_k: "Usines et stock",
      ws3_h: "7 usines, entrepôt de 10 000 m²",
      ws3_p: "Nous détenons des participations dans 7 usines et 4 filiales en Chine, avec des bureaux de vente dans plusieurs provinces — stock, qualité et délais restent entre nos mains.",
      ws3_go: "À propos →",
      ws4_k: "Export depuis 2002",
      ws4_h: "25+ pays et un entrepôt en Arabie saoudite",
      ws4_p: "Distributeurs et ateliers au Moyen-Orient, en Afrique, en Amérique latine et dans la CEI. Notre service export gère un entrepôt en Arabie saoudite : réapprovisionnement plus rapide pour le Golfe et le Moyen-Orient.",
      ws4_go: "Nous contacter →",
      grp_h: "Plus qu'un entrepôt",
