      grp_about: "À propos",
      grp1_t: "7 usines en participation",
      grp1_p: "Nous détenons des participations dans sept usines en Chine — pièces d'injection, capteurs et pompes sont fabriqués selon notre liste OE.",
      grp2_t: "4 filiales, bureaux dans plusieurs provinces",
      grp2_p: "Quatre filiales et bureaux de vente dans plusieurs provinces chinoises gardent achats, qualité et expédition sous une seule gestion.",
      grp3_t: "Entrepôt en Arabie saoudite",
      grp3_p: "Notre service export gère un entrepôt en Arabie saoudite : les acheteurs du Golfe et du Moyen-Orient sont réapprovisionnés plus vite, avec des réassorts plus petits.",
      search_go: "Rechercher",
      bulk_hint: "Une liste de références ? Vérification en lot →",
      prod_h1: "Catalogue produits — 6 819 références",
      rfq_h: "Demander un devis",
      rfq_lead: "Remplissez les quatre champs et ajoutez votre liste de pièces, puis envoyez-la sur WhatsApp — ou par e-mail si vous préférez. Rien n'est envoyé : le bouton ouvre WhatsApp (ou votre messagerie) avec le texte déjà rempli.",
