      faq_h: "Preguntas frecuentes",
      faq_lead: "Las seis preguntas que más nos hacen antes del primer pedido. ¿Otra cosa? Escríbanos por WhatsApp; respondemos en un día laborable.",
      faq_q1: "¿Cuál es el MOQ?",
      faq_a1: "Depende de la referencia y el embalaje. Envíenos las referencias y cantidades y lo confirmamos línea por línea.",
      faq_q2: "¿Cuánto tarda la entrega?",
      faq_a2: "El stock sale de nuestro almacén de Guangzhou en pocos días. Los pedidos de producción dependen de la cantidad: confirmamos la fecha exacta en la cotización.",
      faq_q3: "¿Qué garantía dan?",
      faq_a3: "De 12 a 24 meses según el tipo de pieza. El plazo exacto se escribe en la cotización y en la factura, así que es el mismo para usted y para nosotros.",
      faq_q4: "¿Puedo devolver o cambiar una pieza?",
