      wd_all: "Ver las 6.819 referencias",
      ws1_k: "Lo que suministramos",
      ws1_h: "23 líneas, 6.819 referencias",
      ws1_p: "Bobinas de encendido, bombas de combustible, sondas lambda, sensores ABS, cuerpos de mariposa y bujías: cada pieza con su número OE, presupuesto en un día laborable.",
