      ws2_h: "WEILI y STANDOUT",
      ws2_p: "Fabricadas por socios certificados ISO 9001 / IATF 16949. Controlamos la lista OE, la inspección de entrada, el embalaje y la garantía: por eso las referencias coinciden.",
