      ws4_p: "Distribuidores y talleres en Oriente Medio, África, América Latina y la CEI. Nuestro equipo de exportación gestiona un almacén en Arabia Saudí: reposición más rápida en el Golfo y Oriente Medio.",
      ws4_go: "Contacto →",
