      grp1_t: "7 fábricas participadas",
      grp1_p: "Tenemos participaciones en siete fábricas en China: inyección electrónica, sensores y bombas se fabrican con nuestra lista OE.",
      grp2_t: "4 filiales y sucursales en varias provincias",
      grp2_p: "Cuatro filiales y sucursales en varias provincias chinas mantienen compras, calidad y envío bajo una sola gestión.",
      grp3_t: "Almacén en Arabia Saudí",
      grp3_p: "Nuestro equipo de exportación gestiona un almacén en Arabia Saudí: los compradores del Golfo y Oriente Medio reponen más rápido y con pedidos repetidos más pequeños.",
      search_go: "Buscar",
      bulk_hint: "¿Tienes una lista? Comprobación por lotes →",
      prod_h1: "Catálogo de productos — 6.819 referencias",
      rfq_h: "Solicitar cotización",
      rfq_lead: "Complete los cuatro campos y añada su lista de piezas, luego envíela por WhatsApp — o por correo si lo prefiere. No se sube nada: el botón abre WhatsApp (o su correo) con el texto ya escrito.",
