      payv_t: "Anticipo del 30 % por transferencia (T/T), saldo antes del envío",
      payv_t_note: "Se confirma en la factura proforma antes de pagar",
      payv_lc: "Carta de crédito (L/C) a la vista para pedidos desde 20.000 USD",
