      faq_h: "Pertanyaan umum",
      faq_lead: "Enam hal yang paling sering ditanyakan sebelum pesanan pertama. Ada lagi? Kirim WhatsApp, kami jawab dalam satu hari kerja.",
      faq_q1: "Berapa MOQ-nya?",
      faq_a1: "Tergantung part dan kemasannya. Kirim model dan jumlah yang Anda butuhkan, kami konfirmasi MOQ baris per baris.",
      faq_q2: "Berapa lama pengirimannya?",
      faq_a2: "Stok keluar dari gudang Guangzhou dalam beberapa hari. Pesanan produksi tergantung jumlah — tanggal pasti kami konfirmasi di penawaran.",
      faq_q3: "Garansinya berapa lama?",
      faq_a3: "12 sampai 24 bulan tergantung jenis part. Jangka pastinya tertulis di penawaran dan faktur, jadi sama untuk Anda dan kami.",
      faq_q4: "Bisa retur atau tukar part?",
      faq_a4: "Bisa. Kirim foto masalahnya dan kami ganti atau kreditkan part yang rusak. Tingkat retur kami 0,03%, jadi jarang terjadi.",
      faq_q5: "Bisa minta sampel untuk uji?",
      faq_a5: "Bisa. Sampel tersedia atas permintaan sebelum pesanan besar; ongkos kirim ditanggung pembeli.",
