      about_p1: "Kami adalah Guangzhou Yumengyang Auto Parts Co., Ltd, didirikan tahun 2002 di Distrik Baiyun, Guangzhou: 4 anak perusahaan dan dua merek sendiri, WEILI (pengapian, sensor, sistem bahan bakar) dan STANDOUT.",
