      rfq_h: "Minta penawaran",
      rfq_lead: "Isi empat kolom dan tempelkan daftar part Anda, lalu kirim lewat WhatsApp — atau lewat email jika lebih suka. Tidak ada yang diunggah: tombol membuka WhatsApp (atau aplikasi email Anda) dengan teks yang sudah terisi.",
