      cd_p0301_name: "Misfire pada silinder 1",
      cd_p0301_lead: "P0301 adalah kode misfire paling berguna: ia menyebut silindernya. Sebagian besar yang sampai ke kami adalah sistem pengapian, dan kebanyakan adalah koil, bukan busi.",
      cd_p0301_b_0: "Arti kode ini sebenarnya",
      cd_p0301_b_1: "ECU mengukur seberapa banyak poros engkol bertambah cepat setelah silinder 1 menyala dan membandingkannya dengan silinder lain. Bila kontribusi silinder 1 lebih kecil, ECU menyimpan P0301. Kode ini tercatat pada siklus berkendara kedua berturut-turut yang menunjukkan gangguan, karena itu P0301 yang hilang seminggu lalu muncul lagi biasanya berarti part yang mulai gagal saat panas, bukan kabel putus.",
      cd_p0301_b_2: "Silinder 1 tidak selalu yang paling depan. Pada kebanyakan mesin empat silinder melintang, silinder 1 ada di sisi timing belt, tetapi sebagian pabrikan menomori dari sisi transmisi. Pastikan penomorannya sebelum memesan, terutama pada mesin Prancis dan Korea.",
      cd_p0301_b_3: "Apa yang akan Anda rasakan",
      cd_p0301_b_4_l_0: "Getaran saat idle yang hampir hilang di atas 2.000 rpm — ciri khas koil yang mulai gagal saat panas",
      cd_p0301_b_4_l_1: "Lampu mesin menyala tetap, berkedip saat akselerasi kuat",
      cd_p0301_b_4_l_2: "Getaran yang mulai 10–20 menit setelah start dingin dan makin buruk saat cuaca lembap",
      cd_p0301_b_4_l_3: "Bau bahan bakar di knalpot, konsumsi naik jelas",
      cd_p0301_b_4_l_4: "P0301 muncul bersama P0171 — kombinasi ini biasanya berarti silinder terlalu kurus, bukan api lemah",
      cd_p0301_b_5: "Urutan pemeriksaan kami",
      cd_p0301_b_6_h_0: "Penyebab",
      cd_p0301_b_6_h_1: "Kategori kami",
      cd_p0301_b_6_h_2: "Alasan masuk daftar",
      cd_p0301_b_6_c_0_0: "Busi aus, kotor, atau nilai panasnya salah",
      cd_p0301_b_6_c_0_2: "Part paling murah dan pemeriksaan paling cepat. Insulator yang retak menimbulkan misfire yang sama persis dengan koil mati.",
      cd_p0301_b_6_c_1_0: "Koil silinder 1",
      cd_p0301_b_6_c_1_2: "Penyebab paling umum pada mesin coil-on-plug di atas 100.000 km.",
      cd_p0301_b_6_c_2_0: "Kabel atau boot busi, pada mesin wasted spark",
      cd_p0301_b_6_c_2_2: "Kabel yang tergesek biasanya mematikan dua silinder; boot yang retak hanya satu.",
      cd_p0301_b_6_c_3_0: "Injektor bocor atau tersumbat",
      cd_p0301_b_6_c_3_2: "Silinder kurus menyebabkan misfire. Jika fuel trim di bank itu tinggi, curigai injektornya.",
      cd_p0301_b_6_c_4_0: "Kebocoran gasket intake pada saluran itu",
      cd_p0301_b_6_c_4_2: "Hanya membuat satu silinder kurus, dan makin buruk saat mesin dingin.",
      cd_p0301_b_7: "Uji dulu sebelum membeli",
      cd_p0301_b_8_l_0: "Tukar koil dengan silinder 2 lalu hapus kodenya. Jika misfire pindah ke P0302, koilnya mati. Satu uji ini menyelesaikan sebagian besar kasus dan tidak berbiaya.",
      cd_p0301_b_8_l_1: "Jika kode tetap di silinder 1, lepas busi dan baca: hitam dan basah berarti bahan bakar berlebih atau api lemah; putih dengan elektroda melepuh berarti campuran kurus atau pengapian terlalu maju.",
      cd_p0301_b_8_l_2: "Bandingkan resistansi primer koil dengan koil pada silinder yang Anda tahu baik — jangan dengan angka buku, karena nilainya berbeda antar keluarga koil.",
      cd_p0301_b_8_l_3: "Cari jejak karbon abu-abu tipis di dalam boot, dan oli di sumur busi. Keduanya menyebabkan misfire yang tidak akan beres oleh koil baru sebelum kebocoran oli ditangani.",
      cd_p0301_b_9: "Kesalahan yang mahal",
      cd_p0301_b_10: "Mengganti keempat koil «sekalian tutupnya sudah dibuka» pada mobil 60.000 km. Penyebabnya biasanya busi dan koil jadi korbannya: busi aus butuh tegangan api lebih tinggi dan koil menanggung bebannya. Ganti busi bersama koil, kalau tidak koil itu akan Anda jual lagi dalam setahun.",
      cd_p0301_qa_q0: "P0301 itu koil atau busi?",
      cd_p0301_qa_a0: "Biasanya keduanya: busi aus, koil bekerja lebih berat lalu mati. Memindahkan koil ke silinder lain memberi tahu mana yang mati sekarang; busi tetap harus diganti.",
      cd_p0301_qa_q1: "Bolehkah saya mengemudi dengan P0301?",
      cd_p0301_qa_a1: "Pelan-pelan dan jangan jauh. Lampu menyala tetap berarti segera perbaiki minggu ini; lampu berkedip berarti berhenti, karena bahan bakar terbakar di katalis.",
